:true,"packageVersion":"v3-2026-09-03c","packageContentHash":"f8d4e7273d688f2374d07439295c0177","packageKeyManifestHash":"ad3b78b91851349d48f78053cada7089","packageKeyCount":9271,"packagePartition":"core","packagePartitionContentHash":"53f6cf94236e1da0dfd5ca865889d724","packagePartitionKeyManifestHash":"9a49ed285ab09ef4f98e4c0ef7f8c2d8","packagePartitionKeyCount":7478,"distributionState":null,"releaseBatch":null,"packageBucket":"authored-content","content_role":"full_copy","review_status":"approved","positive_test":null,"readerServing":true,"stageOnly":false,"sourceSchemaVersion":null},"knowledge_ids":[],"source_snapshot":{"contentType":"authored-content","content_role":"full_copy","review_status":"approved","positive_test":null,"approved_via":"owner-final, TLDR-Lunation-Blend-Units-V1.md V2","source_keys":["TLDR-Lunation-Blend-Units-V1.md","packages/astro-knowledge/review/transit-aspect-friends-nonsun-350-owner-live-2026-09-03.json"],"importBatchId":"fallback-architecture-v3-2026-09-03c","sourcePackage":"tldrastro-fallback-architecture-v3","sourceFile":"authored-content","packageVersion":"v3-2026-09-03c","packageContentHash":"f8d4e7273d688f2374d07439295c0177","packageKeyManifestHash":"ad3b78b91851349d48f78053cada7089","packageKeyCount":9271,"packagePartition":"core","packagePartitionContentHash":"53f6cf94236e1da0dfd5ca865889d724","packagePartitionKeyManifestHash":"9a49ed285ab09ef4f98e4c0ef7f8c2d8","packagePartitionKeyCount":7478,"distributionState":null,"releaseBatch":null,"note":"V3 package mirror for dashboard editing. fallback_source rows are source material and must never render directly."},"reviewer_notes":"","prompt_version":"fallback-architecture-v3-2026-09-03c","provider":"tldrastro-fallback-architecture-v3","model":"manual","updated_at":"2026-09-04T14:21:31.223Z"}]$tldr_transit_v3$::jsonb) as x(
  content_key text,
  surface text,
  mode text,
  status text,
  event_type text,
  target_date date,
  headline text,
  summary text,
  body text,
  sections jsonb,
  block_type text,
  lane text,
  review_state text,
  evergreen boolean,
  evergreen_at timestamptz,
  evergreen_by text,
  facts jsonb,
  knowledge_ids text[],
