);

do $guard$
declare
  live_count integer;
  live_distinct_count integer;
  expected_count integer;
  you_drift_count integer;
  sun_friend_drift_count integer;
  existing_friend_count integer;
  existing_nonsun_friend_count integer;
begin
  select count(*), count(distinct content_key) into live_count, live_distinct_count
  from public.generated_interpretations
  where provider = 'tldrastro-fallback-architecture-v3'
    and content_key like 'authored/transit-aspect/%';

  select count(*) into expected_count from expected_transit_dashboard_rows;

  if live_count <> 378 or live_distinct_count <> 378 or expected_count <> 378 then
    raise exception 'Transit mirror precondition failed: live %, distinct %, expected %', live_count, live_distinct_count, expected_count;
  end if;

  select count(*) into you_drift_count
  from expected_transit_dashboard_rows e
  join public.generated_interpretations g
    on g.content_key = e.content_key
   and g.provider = 'tldrastro-fallback-architecture-v3'
  where encode(digest(coalesce(g.sections->>'body_you', ''), 'sha256'), 'hex')
        is distinct from
        encode(digest(coalesce(e.sections->>'body_you', ''), 'sha256'), 'hex');

  if you_drift_count <> 0 then
    raise exception 'Refusing transit mirror sync: % live You rows drift from the canonical package', you_drift_count;
  end if;

  select count(*) into existing_friend_count
  from public.generated_interpretations
  where provider = 'tldrastro-fallback-architecture-v3'
    and content_key like 'authored/transit-aspect/%'
    and coalesce(nullif(trim(sections->>'body_they'), ''), '') <> '';

  select count(*) into existing_nonsun_friend_count
  from public.generated_interpretations
  where provider = 'tldrastro-fallback-architecture-v3'
    and content_key like 'authored/transit-aspect/%'
    and content_key not like 'authored/transit-aspect/sun/%'
    and coalesce(nullif(trim(sections->>'body_they'), ''), '') <> '';

  if existing_friend_count <> 27 or existing_nonsun_friend_count <> 0 then
    raise exception 'Unexpected pre-release Friends baseline: explicit %, non-Sun %', existing_friend_count, existing_nonsun_friend_count;
  end if;

  select count(*) into sun_friend_drift_count
  from expected_transit_dashboard_rows e
  join public.generated_interpretations g
    on g.content_key = e.content_key
   and g.provider = 'tldrastro-fallback-architecture-v3'
  where e.content_key like 'authored/transit-aspect/sun/%'
    and encode(digest(coalesce(g.sections->>'body_they', ''), 'sha256'), 'hex')
        is distinct from
        encode(digest(coalesce(e.sections->>'body_they', ''), 'sha256'), 'hex');

  if sun_friend_drift_count <> 0 then
    raise exception 'Refusing transit mirror sync: % preserved Sun Friends rows drift from canonical package', sun_friend_drift_count;
  end if;

  if exists (
    select 1
    from public.generated_interpretations
    where provider = 'tldrastro-fallback-architecture-v3'
      and content_key = 'authored/transit-aspect/venus/moon/hard'
      and (
        sections->>'body_they' is not null
        or encode(digest(coalesce(sections->>'body_you', ''), 'sha256'), 'hex') <> '254f56e3bb9ed7b1d29215b2aa3e92d22877c24925932e703a097ceb2416334a'
      )
  ) then
    raise exception 'Protected Venus square Moon live row drifted before sync';
  end if;
end
$guard$;

update public.generated_interpretations g
set
  surface = e.surface,
  mode = e.mode,
  status = e.status,
  event_type = e.event_type,
  target_date = e.target_date,
  headline = e.headline,
  summary = e.summary,
  body = e.body,
  sections = e.sections,
  block_type = e.block_type,
  lane = e.lane,
  review_state = e.review_state,
  evergreen = e.evergreen,
  evergreen_at = e.evergreen_at,
  evergreen_by = e.evergreen_by,
  facts = e.facts,
  knowledge_ids = coalesce(e.knowledge_ids, '{}'::text[]),
  source_snapshot = e.source_snapshot,
  reviewer_notes = e.reviewer_notes,
  prompt_version = e.prompt_version,
  provider = e.provider,
  model = e.model,
  updated_at = e.updated_at
from expected_transit_dashboard_rows e
where g.content_key = e.content_key
  and g.provider = 'tldrastro-fallback-architecture-v3';

do $verify$
declare
  mismatch_count integer;
  explicit_friend_count integer;
  explicit_sun_friend_count integer;
  explicit_nonsun_friend_count integer;
  friend_hash_drift_count integer;
begin
  select count(*) into mismatch_count
  from expected_transit_dashboard_rows e
  join public.generated_interpretations g
    on g.content_key = e.content_key
   and g.provider = 'tldrastro-fallback-architecture-v3'
  where g.surface is distinct from e.surface
     or g.mode is distinct from e.mode
     or g.status is distinct from e.status
     or g.event_type is distinct from e.event_type
     or g.target_date is distinct from e.target_date
     or g.headline is distinct from e.headline
     or g.summary is distinct from e.summary
     or g.body is distinct from e.body
     or g.sections is distinct from e.sections
     or g.block_type is distinct from e.block_type
     or g.lane is distinct from e.lane
     or g.review_state is distinct from e.review_state
     or g.facts is distinct from e.facts
     or g.source_snapshot is distinct from e.source_snapshot
     or g.prompt_version is distinct from e.prompt_version
     or g.provider is distinct from e.provider
     or g.model is distinct from e.model;

  if mismatch_count <> 0 then
    raise exception 'Canonical transit mirror verification failed for % rows', mismatch_count;
  end if;

  select
    count(*) filter (where coalesce(nullif(trim(sections->>'body_they'), ''), '') <> ''),
    count(*) filter (where content_key like 'authored/transit-aspect/sun/%' and coalesce(nullif(trim(sections->>'body_they'), ''), '') <> ''),
    count(*) filter (where content_key not like 'authored/transit-aspect/sun/%' and coalesce(nullif(trim(sections->>'body_they'), ''), '') <> '')
  into explicit_friend_count, explicit_sun_friend_count, explicit_nonsun_friend_count
  from public.generated_interpretations
  where provider = 'tldrastro-fallback-architecture-v3'
    and content_key like 'authored/transit-aspect/%';

  if explicit_friend_count <> 377 or explicit_sun_friend_count <> 27 or explicit_nonsun_friend_count <> 350 then
    raise exception 'Friends count verification failed: total %, Sun %, non-Sun %', explicit_friend_count, explicit_sun_friend_count, explicit_nonsun_friend_count;
  end if;

  select count(*) into friend_hash_drift_count
  from public.generated_interpretations
  where provider = 'tldrastro-fallback-architecture-v3'
    and content_key like 'authored/transit-aspect/%'
    and coalesce(nullif(trim(sections->>'body_they'), ''), '') <> ''
    and (
      sections->'packageRecord'->>'body_they_sha256' is null
      or sections->'packageRecord'->>'body_they_sha256' <> encode(digest(sections->>'body_they', 'sha256'), 'hex')
    );

  if friend_hash_drift_count <> 0 then
    raise exception 'Friends SHA verification failed for % rows', friend_hash_drift_count;
  end if;

  if exists (
    select 1
    from public.generated_interpretations
    where provider = 'tldrastro-fallback-architecture-v3'
      and content_key = 'authored/transit-aspect/venus/moon/hard'
      and (
        sections->>'body_they' is not null
        or encode(digest(coalesce(sections->>'body_you', ''), 'sha256'), 'hex') <> '254f56e3bb9ed7b1d29215b2aa3e92d22877c24925932e703a097ceb2416334a'
      )
  ) then
    raise exception 'Protected Venus square Moon verification failed after sync';
  end if;
end
$verify$;
